using Avalonia;
using Avalonia.Controls;
using Avalonia.Threading;
using Daqifi.Desktop.ViewModels;

namespace Daqifi.Desktop.View.Prototype;

/// <summary>
/// Host UserControl for the unified Devices pane. Owns the
/// <see cref="DevicesPaneViewModel"/> lifecycle — recreates the VM each time
/// the pane is attached (TabControl switches detach and re-attach it) so a
/// returning tab picks up devices connected while it was detached, and
/// disposes the VM on detach to drop the singleton subscription.
/// </summary>
// @port: Daqifi.Desktop.View.Prototype.DevicesPanePrototype
public partial class DevicesPanePrototype : UserControl
{
    /// <summary>Creates the pane; the VM lifecycle follows visual-tree attachment.</summary>
    public DevicesPanePrototype()
    {
        InitializeComponent();
    }

    // Upstream swaps the VM in on Loaded. Avalonia raises Loaded at DispatcherPriority.Loaded,
    // BELOW Render, so the pane was laid out and presented for a frame with the host's
    // DaqifiViewModel (first visit) or null (every later one) — every IsSettingsOpen /
    // HasConnectedDevice gate at its default true, drawer drawn open (#397). Attach runs
    // synchronously, before any layout of the pane, so no frame ever sees the wrong DataContext.
    // @port: Daqifi.Desktop.View.Prototype.DevicesPanePrototype.OnLoaded
    protected override void OnAttachedToVisualTree(VisualTreeAttachmentEventArgs e)
    {
        if (DataContext is not DevicesPaneViewModel)
        {
            // WPF Window.GetWindow(this) → TopLevel.GetTopLevel(this).
            var shell = (TopLevel.GetTopLevel(this) as Window)?.DataContext as DaqifiViewModel;
            DataContext = new DevicesPaneViewModel(shell);
        }
        FollowFirmwareSectionRequests();
        base.OnAttachedToVisualTree(e);
    }

    /// <summary>
    /// Moves keyboard focus to CANCEL when the firmware-update prompt opens (issue #564), so the
    /// safe choice is the default and Enter does not start a write. The same deferral as the Logged
    /// Data pane's confirm overlay: focusing inside the change handler can race the visibility switch.
    /// </summary>
    private void OnFirmwareUpdateConfirmIsVisibleChanged(object? sender, AvaloniaPropertyChangedEventArgs e)
    {
        if (e.Property == IsVisibleProperty && e.NewValue is true)
        {
            Dispatcher.UIThread.Post(
                () => this.FindControl<Button>("FirmwareConfirmCancelButton")?.Focus(),
                DispatcherPriority.Input);
        }
    }

    // @port: Daqifi.Desktop.View.Prototype.DevicesPanePrototype.OnUnloaded
    protected override void OnDetachedFromVisualTree(VisualTreeAttachmentEventArgs e)
    {
        base.OnDetachedFromVisualTree(e);
        if (DataContext is DevicesPaneViewModel pane)
        {
            pane.FirmwareSectionShown -= OnFirmwareSectionShown;
        }
        if (DataContext is IDisposable disposable)
        {
            disposable.Dispose();
            DataContext = null;
        }
    }

    /// <summary>
    /// Subscribes to the view model's FIRMWARE-section requests (issue #569), and serves the one it
    /// took while it was being built, before this subscription existed.
    /// </summary>
    private void FollowFirmwareSectionRequests()
    {
        if (DataContext is not DevicesPaneViewModel pane) return;
        pane.FirmwareSectionShown += OnFirmwareSectionShown;
        if (pane.TakeFirmwareScrollRequest()) ScrollToFirmwareSection();
    }

    private void OnFirmwareSectionShown(object? sender, EventArgs e)
    {
        if ((sender as DevicesPaneViewModel)?.TakeFirmwareScrollRequest() == true) ScrollToFirmwareSection();
    }

    /// <summary>
    /// Scrolls the drawer so the FIRMWARE section starts at the top of its view (issue #569). The
    /// drawer has only now become visible, so this waits for the layout pass that measures it.
    /// </summary>
    private void ScrollToFirmwareSection()
    {
        Dispatcher.UIThread.Post(() =>
        {
            var section = this.FindControl<TextBlock>("FirmwareSection");
            if (section == null) return;
            // A rectangle one viewport tall from the label down, so the label lands at the top of
            // the view and not at its bottom edge with the controls under it out of sight.
            var viewer = global::Avalonia.VisualTree.VisualExtensions.FindAncestorOfType<ScrollViewer>(section);
            var viewportHeight = viewer?.Viewport.Height ?? 0;
            section.BringIntoView(new Rect(0, 0, section.Bounds.Width, Math.Max(section.Bounds.Height, viewportHeight)));
        }, DispatcherPriority.Loaded);
    }
}
